 select customer.firstname, customer.lastname, genre.name from customer left join invoice on invoice.customerid = customer.customerid left join invoiceline on invoiceline.invoiceid = invoice.invoiceid left join track on track.trackid = invoiceline.trackid left join genre on genre.genreid = track.genreid group by customer.customerid, genre.genreid having count(track.trackid) = (select max(genre_count) from (select count(track.trackid) as genre_count from invoice left join invoiceline on invoiceline.invoiceid = invoice.invoiceid left join track on track.trackid = invoiceline.trackid where invoice.customerid = customer.customerid group by track.genreid)) order by customer.firstname, customer.lastname;
 